//! Rust port of tree-sitter-haskell's external scanner (src/scanner.c and its src/unicode.h,
//! tree-sitter-haskell 0.23.1). The function order and names follow the C.
//!
//! Locale: the C scanner calls no `isw*` function. Its character classes come from the generated
//! bitmaps of `unicode.h` (`is_identifier_char`, `is_varid_start_char`, `is_conid_start_char`,
//! `is_symop_char`, `is_space_char`), which are copied verbatim at the end of this file.
//!
//! Representation: every C enum (`Symbol`, `ContextSort`, `Lexed`, `NewlineState`, ...) is a `u32`
//! alias with constants, so that arithmetic, comparisons and the `SEQ` short circuit work as in the C
//! and so that a corrupt serialized buffer cannot create an invalid enum value.
//!
//! Deviations from the C (all in code paths where the C reads or writes out of bounds):
//! - `deserialize` with a buffer shorter than the header, or whose context count exceeds the bytes
//!   present, reads what is there and zero-fills the rest instead of reading past the buffer.
//! - `serialize` writes the 20 byte header and then returns 0 if the contexts do not fit in the
//!   1024 byte buffer, exactly as the C does (the C's header write is always in bounds).
//! - `start_column` and the other `uint32_t` arithmetic wrap as in the C.
#![allow(clippy::all, unsafe_op_in_unsafe_fn, dead_code, non_snake_case)]
use crate::abi::TSLexer;
use core::ffi::{c_char, c_void};

const SERIALIZATION_BUFFER_SIZE: u32 = 1024;

/// Short circuit a parse step: if the argument expression is non-zero, return it.
macro_rules! SEQ {
    ($e:expr) => {{
        let res: u32 = $e;
        if res != 0 {
            return res;
        }
    }};
}

// ---------------------------------------------------------------------------------------------
// Symbols
// ---------------------------------------------------------------------------------------------

type Symbol = u32;
const FAIL: Symbol = 0;
const SEMICOLON: Symbol = 1;
const START: Symbol = 2;
const START_DO: Symbol = 3;
const START_CASE: Symbol = 4;
const START_IF: Symbol = 5;
const START_LET: Symbol = 6;
const START_QUOTE: Symbol = 7;
const START_EXPLICIT: Symbol = 8;
const END: Symbol = 9;
const END_EXPLICIT: Symbol = 10;
const START_BRACE: Symbol = 11;
const END_BRACE: Symbol = 12;
const START_TEXP: Symbol = 13;
const END_TEXP: Symbol = 14;
const WHERE: Symbol = 15;
const IN: Symbol = 16;
const ARROW: Symbol = 17;
const BAR: Symbol = 18;
const DERIVING: Symbol = 19;
const COMMENT: Symbol = 20;
const HADDOCK: Symbol = 21;
const CPP: Symbol = 22;
const PRAGMA: Symbol = 23;
const QQ_START: Symbol = 24;
const QQ_BODY: Symbol = 25;
const SPLICE: Symbol = 26;
const QUAL_DOT: Symbol = 27;
const TIGHT_DOT: Symbol = 28;
const PREFIX_DOT: Symbol = 29;
const DOTDOT: Symbol = 30;
const TIGHT_AT: Symbol = 31;
const PREFIX_AT: Symbol = 32;
const TIGHT_BANG: Symbol = 33;
const PREFIX_BANG: Symbol = 34;
const TIGHT_TILDE: Symbol = 35;
const PREFIX_TILDE: Symbol = 36;
const PREFIX_PERCENT: Symbol = 37;
const QUALIFIED_OP: Symbol = 38;
const LEFT_SECTION_OP: Symbol = 39;
const NO_SECTION_OP: Symbol = 40;
const MINUS: Symbol = 41;
const CONTEXT: Symbol = 42;
const INFIX: Symbol = 43;
const DATA_INFIX: Symbol = 44;
const TYPE_INSTANCE: Symbol = 45;
const VARSYM: Symbol = 46;
const CONSYM: Symbol = 47;
const UPDATE: Symbol = 48;

// ---------------------------------------------------------------------------------------------
// Data
// ---------------------------------------------------------------------------------------------

type ContextSort = u32;
const DECL_LAYOUT: ContextSort = 0;
const DO_LAYOUT: ContextSort = 1;
const CASE_LAYOUT: ContextSort = 2;
const LET_LAYOUT: ContextSort = 3;
const QUOTE_LAYOUT: ContextSort = 4;
const MULTI_WAY_IF_LAYOUT: ContextSort = 5;
const BRACES: ContextSort = 6;
const T_EXP: ContextSort = 7;
const MODULE_HEADER: ContextSort = 8;
const NO_CONTEXT: ContextSort = 9;

#[derive(Clone, Copy)]
struct Context {
    sort: ContextSort,
    indent: u32,
}

type Lexed = u32;
const L_NOTHING: Lexed = 0;
const L_EOF: Lexed = 1;
const L_WHERE: Lexed = 2;
const L_IN: Lexed = 3;
const L_THEN: Lexed = 4;
const L_ELSE: Lexed = 5;
const L_DERIVING: Lexed = 6;
const L_MODULE: Lexed = 7;
const L_UPPER: Lexed = 8;
const L_TICK: Lexed = 9;
const L_SYMOP: Lexed = 10;
const L_SYMOP_SPECIAL: Lexed = 11;
const L_DOT_DOT: Lexed = 12;
const L_DOT_ID: Lexed = 13;
const L_DOT_SYMOP: Lexed = 14;
const L_DOT_OPEN: Lexed = 15;
const L_DOLLAR: Lexed = 16;
const L_BANG: Lexed = 17;
const L_TILDE: Lexed = 18;
const L_AT: Lexed = 19;
const L_PERCENT: Lexed = 20;
const L_HASH: Lexed = 21;
const L_BAR: Lexed = 22;
const L_ARROW: Lexed = 23;
const L_C_ARROW: Lexed = 24;
const L_TEXP_CLOSER: Lexed = 25;
const L_QUOTE_CLOSE: Lexed = 26;
const L_PRAGMA: Lexed = 27;
const L_BLOCK_COMMENT: Lexed = 28;
const L_LINE_COMMENT: Lexed = 29;
const L_BRACE_CLOSE: Lexed = 30;
const L_BRACE_OPEN: Lexed = 31;
const L_BRACKET_OPEN: Lexed = 32;
const L_UNBOXED_CLOSE: Lexed = 33;
const L_SEMI: Lexed = 34;
const L_CPP_ELSE: Lexed = 35;
const L_CPP: Lexed = 36;

type NewlineState = u32;
const N_INACTIVE: NewlineState = 0;
const N_INIT: NewlineState = 1;
const N_PROCESS: NewlineState = 2;
const N_RESUME: NewlineState = 3;

/// Layout of the C `Newline` struct: `state`, `end`, `indent` (4 bytes each), then four bools.
#[derive(Clone, Copy, Default)]
struct Newline {
    state: NewlineState,
    end: Lexed,
    indent: u32,
    eof: bool,
    no_semi: bool,
    skip_semi: bool,
    unsafe_: bool,
}

/// `Lookahead`: the buffer is `contents` (its length is the C `size`), plus `offset`.
#[derive(Default)]
struct Lookahead {
    contents: Vec<i32>,
    offset: u32,
}

struct State {
    contexts: Vec<Context>,
    newline: Newline,
    lookahead: Lookahead,
}

struct Env<'a> {
    lexer: *mut TSLexer,
    symbols: *const bool,
    symop: u32,
    state: &'a mut State,
}

fn env_new<'a>(l: *mut TSLexer, symbols: *const bool, state: &'a mut State) -> Env<'a> {
    Env {
        lexer: l,
        symbols,
        symop: 0,
        state,
    }
}

fn reset_newline(env: &mut Env) {
    env.state.newline = Newline::default();
}

fn newline_active(env: &mut Env) -> bool {
    env.state.newline.state == N_INIT || env.state.newline.state == N_PROCESS
}

fn newline_init(env: &mut Env) -> bool {
    env.state.newline.state == N_INIT
}

// ---------------------------------------------------------------------------------------------
// Lexer interaction
// ---------------------------------------------------------------------------------------------

/// `PEEK`: `env->lexer->lookahead`.
unsafe fn PEEK(env: &Env) -> i32 {
    (*env.lexer).lookahead
}

unsafe fn is_eof(env: &Env) -> bool {
    ((*env.lexer).eof)(env.lexer)
}

unsafe fn not_eof(env: &Env) -> bool {
    !is_eof(env)
}

/// The parser's position in the current line.
unsafe fn column(env: &Env) -> u32 {
    if is_eof(env) {
        0
    } else {
        ((*env.lexer).get_column)(env.lexer)
    }
}

/// Append the lookahead character to the lookahead buffer and advance (no-op at EOF).
unsafe fn advance(env: &mut Env) {
    if not_eof(env) {
        let c = PEEK(env);
        env.state.lookahead.contents.push(c);
        ((*env.lexer).advance)(env.lexer, false);
    }
}

/// `S_ADVANCE`
unsafe fn s_advance(env: &mut Env) {
    advance(env);
}

/// `S_SKIP`
unsafe fn s_skip(env: &mut Env) {
    ((*env.lexer).advance)(env.lexer, true);
}

/// `MARK(s)`
unsafe fn mark(env: &mut Env) {
    ((*env.lexer).mark_end)(env.lexer);
}

unsafe fn set_result_symbol(env: &mut Env, result: Symbol) -> bool {
    if result != FAIL {
        (*env.lexer).result_symbol = result as u16;
        return true;
    }
    false
}

unsafe fn valid(env: &Env, s: Symbol) -> bool {
    *env.symbols.add(s as usize)
}

// ---------------------------------------------------------------------------------------------
// Symbol constructors
// ---------------------------------------------------------------------------------------------

fn finish(s: Symbol) -> Symbol {
    s
}

unsafe fn finish_if_valid(env: &Env, s: Symbol) -> Symbol {
    if valid(env, s) {
        return finish(s);
    }
    FAIL
}

unsafe fn finish_marked(env: &mut Env, s: Symbol) -> Symbol {
    mark(env);
    s
}

fn update_state() -> Symbol {
    finish(UPDATE)
}

// ---------------------------------------------------------------------------------------------
// Lookahead
// ---------------------------------------------------------------------------------------------

fn la_size(env: &Env) -> u32 {
    env.state.lookahead.contents.len() as u32
}

unsafe fn advance_over_abs(env: &mut Env, abs: u32) {
    let mut i = la_size(env);
    while i <= abs {
        s_advance(env);
        i = i.wrapping_add(1);
    }
}

unsafe fn advance_over(env: &mut Env, rel: u32) {
    advance_over_abs(env, env.state.lookahead.offset.wrapping_add(rel));
}

unsafe fn skip_over(env: &mut Env, rel: u32) {
    let offset = env.state.lookahead.offset;
    // Subtraction is safe because the condition establishes that `offset` is at least 1
    if offset > la_size(env) {
        advance_over_abs(env, offset - 1);
    }
    let abs = env.state.lookahead.offset.wrapping_add(rel);
    let mut i = la_size(env);
    while i <= abs {
        s_skip(env);
        i = i.wrapping_add(1);
    }
}

unsafe fn advance_before(env: &mut Env, rel: u32) {
    let abs = env.state.lookahead.offset.wrapping_add(rel);
    if abs > 0 {
        advance_over_abs(env, abs - 1);
    }
}

fn unsafe_peek_abs(env: &Env, abs: u32) -> i32 {
    if abs < la_size(env) {
        env.state.lookahead.contents[abs as usize]
    } else {
        0
    }
}

fn unsafe_peek(env: &Env, rel: u32) -> i32 {
    unsafe_peek_abs(env, env.state.lookahead.offset.wrapping_add(rel))
}

unsafe fn peek(env: &mut Env, rel: u32) -> i32 {
    if env.state.lookahead.offset.wrapping_add(rel) < la_size(env) {
        unsafe_peek(env, rel)
    } else {
        advance_before(env, rel);
        PEEK(env)
    }
}

unsafe fn peek0(env: &mut Env) -> i32 {
    peek(env, 0)
}

unsafe fn peek1(env: &mut Env) -> i32 {
    peek(env, 1)
}

unsafe fn peek2(env: &mut Env) -> i32 {
    peek(env, 2)
}

unsafe fn char_at(env: &mut Env, n: u32, c: i32) -> bool {
    peek(env, n) == c
}

unsafe fn char0(env: &mut Env, c: i32) -> bool {
    char_at(env, 0, c)
}

unsafe fn char1(env: &mut Env, c: i32) -> bool {
    char_at(env, 1, c)
}

unsafe fn char2(env: &mut Env, c: i32) -> bool {
    char_at(env, 2, c)
}

fn reset_lookahead_abs(env: &mut Env, abs: u32) {
    env.state.lookahead.offset = abs;
    env.symop = 0;
}

fn reset_lookahead_to(env: &mut Env, rel: u32) {
    reset_lookahead_abs(env, env.state.lookahead.offset.wrapping_add(rel));
}

fn reset_lookahead(env: &mut Env) {
    let size = la_size(env);
    reset_lookahead_abs(env, size);
}

fn no_lookahead(env: &Env) -> bool {
    la_size(env) == 0
}

unsafe fn start_column(env: &Env) -> u32 {
    column(env).wrapping_sub(la_size(env))
}

unsafe fn advance_while(env: &mut Env, mut i: u32, pred: fn(i32) -> bool) -> u32 {
    while pred(peek(env, i)) {
        i = i.wrapping_add(1);
    }
    i
}

unsafe fn advance_until_char(env: &mut Env, mut i: u32, c: i32) -> u32 {
    while not_eof(env) && !char_at(env, i, c) {
        i = i.wrapping_add(1);
    }
    i
}

// ---------------------------------------------------------------------------------------------
// Context manipulation and conditions
// ---------------------------------------------------------------------------------------------

fn has_contexts(env: &Env) -> bool {
    !env.state.contexts.is_empty()
}

fn push_context(env: &mut Env, sort: ContextSort, indent: u32) {
    env.state.contexts.push(Context { sort, indent });
}

fn pop(env: &mut Env) {
    if has_contexts(env) {
        env.state.contexts.pop();
    }
}

fn current_context(env: &Env) -> ContextSort {
    match env.state.contexts.last() {
        Some(c) => c.sort,
        None => NO_CONTEXT,
    }
}

fn is_layout_context(env: &Env) -> bool {
    current_context(env) < BRACES
}

fn is_semicolon_context(env: &Env) -> bool {
    current_context(env) < MULTI_WAY_IF_LAYOUT
}

fn current_indent(env: &Env) -> u32 {
    let mut i = env.state.contexts.len() as i32 - 1;
    while i >= 0 {
        let cur = &env.state.contexts[i as usize];
        if cur.sort < BRACES {
            return cur.indent;
        }
        i -= 1;
    }
    0
}

fn indent_less(env: &Env, indent: u32) -> bool {
    is_layout_context(env) && indent < current_indent(env)
}

fn indent_lesseq(env: &Env, indent: u32) -> bool {
    is_layout_context(env) && indent <= current_indent(env)
}

fn top_layout(env: &Env) -> bool {
    env.state.contexts.len() == 1
}

fn in_module_header(env: &Env) -> bool {
    current_context(env) == MODULE_HEADER
}

fn context_end_sym(s: ContextSort) -> Symbol {
    match s {
        T_EXP => END_TEXP,
        BRACES => END_BRACE,
        _ => {
            if s < BRACES {
                END
            } else {
                FAIL
            }
        }
    }
}

// ---------------------------------------------------------------------------------------------
// Character and lookahead conditions
// ---------------------------------------------------------------------------------------------

fn is_newline(c: i32) -> bool {
    matches!(c, 0x0a | 0x0d | 0x0c)
}

fn varid_start_char(c: i32) -> bool {
    c == '_' as i32 || is_varid_start_char(c)
}

fn is_id_char(c: i32) -> bool {
    c == '_' as i32 || c == '\'' as i32 || is_identifier_char(c)
}

fn is_inner_id_char(c: i32) -> bool {
    is_id_char(c) || c == '#' as i32
}

fn quoter_char(c: i32) -> bool {
    is_id_char(c) || c == '.' as i32
}

fn reserved_symbolic(c: i32) -> bool {
    matches!(
        c,
        0x28 | 0x29 | 0x2c | 0x3b | 0x5b | 0x5d | 0x60 | 0x7b | 0x7d | 0x22 | 0x27 | 0x5f
    )
}

fn symop_char(c: i32) -> bool {
    is_symop_char(c) && !reserved_symbolic(c)
}

unsafe fn symop_lookahead(env: &mut Env) -> u32 {
    if env.symop == 0 {
        env.symop = advance_while(env, 0, symop_char);
    }
    env.symop
}

unsafe fn is_symop(env: &mut Env) -> bool {
    symop_lookahead(env) > 0
}

unsafe fn after_error(env: &Env) -> bool {
    valid(env, FAIL)
}

// ---------------------------------------------------------------------------------------------
// Lookahead
// ---------------------------------------------------------------------------------------------

unsafe fn seq_from(env: &mut Env, s: &str, start: u32) -> bool {
    let len = s.len() as u32;
    let b = s.as_bytes();
    for i in 0..len {
        let c = b[i as usize] as i8 as i32;
        let c2 = peek(env, start.wrapping_add(i));
        if c != c2 {
            return false;
        }
    }
    peek(env, start.wrapping_add(len));
    true
}

unsafe fn seq(env: &mut Env, s: &str) -> bool {
    seq_from(env, s, 0)
}

unsafe fn take_line(env: &mut Env) {
    while not_eof(env) && !is_newline(PEEK(env)) {
        s_advance(env);
    }
}

fn is_space_or_tab(c: i32) -> bool {
    c == ' ' as i32 || c == '\t' as i32
}

unsafe fn take_line_escaped_newline(env: &mut Env) {
    loop {
        while not_eof(env) && !is_newline(PEEK(env)) && PEEK(env) != '\\' as i32 {
            s_advance(env);
        }
        if PEEK(env) == '\\' as i32 {
            s_advance(env);
            if is_space_or_tab(PEEK(env)) {
                while is_space_or_tab(PEEK(env)) {
                    s_advance(env);
                }
                if is_newline(PEEK(env)) {
                    s_advance(env);
                }
            } else {
                s_advance(env);
            }
        } else {
            return;
        }
    }
}

unsafe fn skip_space(env: &mut Env) -> bool {
    if !is_space_char(PEEK(env)) {
        return false;
    }
    s_skip(env);
    while is_space_char(PEEK(env)) {
        s_skip(env);
    }
    true
}

unsafe fn skip_newlines(env: &mut Env) -> bool {
    if !is_newline(PEEK(env)) {
        return false;
    }
    s_skip(env);
    while is_newline(PEEK(env)) {
        s_skip(env);
    }
    true
}

type Space = u32;
const NO_SPACE: Space = 0;
const INDENTED: Space = 1;
const BOL: Space = 2;

unsafe fn skip_whitespace(env: &mut Env) -> Space {
    let mut space = NO_SPACE;
    loop {
        if skip_space(env) {
            space = INDENTED;
        } else if skip_newlines(env) {
            space = BOL;
        } else {
            return space;
        }
    }
}

unsafe fn take_space_from(env: &mut Env, start: u32) -> u32 {
    advance_while(env, start, is_space_char)
}

fn token_end(c: i32) -> bool {
    !is_inner_id_char(c)
}

unsafe fn token_from(env: &mut Env, s: &str, start: u32) -> bool {
    seq_from(env, s, start) && {
        let at = start.wrapping_add(s.len() as u32);
        token_end(peek(env, at))
    }
}

unsafe fn token(env: &mut Env, s: &str) -> bool {
    seq(env, s) && token_end(peek(env, s.len() as u32))
}

unsafe fn any_token_from(env: &mut Env, tokens: &[&str], start: u32) -> bool {
    for t in tokens {
        if token_from(env, t, start) {
            return true;
        }
    }
    false
}

unsafe fn match_symop(env: &mut Env, target: &str) -> bool {
    symop_lookahead(env) as usize == target.len() && seq(env, target)
}

fn uninitialized(env: &Env) -> bool {
    !has_contexts(env)
}

unsafe fn conid(env: &mut Env) -> u32 {
    if !is_conid_start_char(peek0(env)) {
        return 0;
    }
    advance_while(env, 1, is_inner_id_char)
}

type QualifiedName = u32;
const NO_QUALIFIED_NAME: QualifiedName = 0;
const QUALIFIED_TARGET: QualifiedName = 1;
const QUALIFIED_CONID: QualifiedName = 2;

unsafe fn qualified_name(env: &mut Env, name: unsafe fn(&mut Env) -> bool) -> QualifiedName {
    let mut qualified = false;
    loop {
        let end = conid(env);
        if end == 0 {
            break;
        }
        if !char_at(env, end, '.' as i32) {
            if qualified {
                return QUALIFIED_CONID;
            } else {
                break;
            }
        }
        qualified = true;
        reset_lookahead_to(env, end.wrapping_add(1));
        if name(env) {
            return QUALIFIED_TARGET;
        }
    }
    NO_QUALIFIED_NAME
}

unsafe fn odd_backslashes_before(env: &mut Env, mut index: i32) -> bool {
    let mut odd = false;
    while index >= 0 && peek(env, index as u32) == '\\' as i32 {
        odd = !odd;
        index -= 1;
    }
    odd
}

unsafe fn take_string_literal(env: &mut Env) -> u32 {
    let mut end: u32 = 1;
    loop {
        end = advance_until_char(env, end, '"' as i32).wrapping_add(1);
        if is_eof(env) || !odd_backslashes_before(env, (end as i32).wrapping_sub(2)) {
            return end;
        }
    }
}

unsafe fn take_char_literal(env: &mut Env) -> u32 {
    if char1(env, '\\' as i32) {
        advance_until_char(env, 2, '\'' as i32).wrapping_add(2)
    } else if char_at(env, 2, '\'' as i32) {
        3
    } else {
        1
    }
}

// ---------------------------------------------------------------------------------------------
// Lookahead: CPP
// ---------------------------------------------------------------------------------------------

type CppDirective = u32;
const CPP_NOTHING: CppDirective = 0;
const CPP_START: CppDirective = 1;
const CPP_ELSE: CppDirective = 2;
const CPP_END: CppDirective = 3;
const CPP_OTHER: CppDirective = 4;

const CPP_TOKENS_START: [&str; 3] = ["if", "ifdef", "ifndef"];

unsafe fn cpp_cond_start(env: &mut Env, start: u32) -> bool {
    any_token_from(env, &CPP_TOKENS_START, start)
}

const CPP_TOKENS_ELSE: [&str; 4] = ["else", "elif", "elifdef", "elifndef"];

unsafe fn cpp_cond_else(env: &mut Env, start: u32) -> bool {
    any_token_from(env, &CPP_TOKENS_ELSE, start)
}

unsafe fn cpp_cond_end(env: &mut Env, start: u32) -> bool {
    token_from(env, "endif", start)
}

const CPP_TOKENS_OTHER: [&str; 7] = [
    "define", "undef", "include", "pragma", "error", "warning", "line",
];

unsafe fn cpp_directive_other(env: &mut Env, start: u32) -> bool {
    any_token_from(env, &CPP_TOKENS_OTHER, start)
        || is_newline(peek(env, start))
        // shebang for scripts
        || (char1(env, '!' as i32) && uninitialized(env))
}

unsafe fn cpp_directive(env: &mut Env) -> CppDirective {
    if !char0(env, '#' as i32) {
        return CPP_NOTHING;
    }
    let start = take_space_from(env, 1);
    if cpp_cond_start(env, start) {
        CPP_START
    } else if cpp_cond_else(env, start) {
        CPP_ELSE
    } else if cpp_cond_end(env, start) {
        CPP_END
    } else if cpp_directive_other(env, start) {
        CPP_OTHER
    } else {
        CPP_NOTHING
    }
}

// ---------------------------------------------------------------------------------------------
// Starting layouts
// ---------------------------------------------------------------------------------------------

unsafe fn start_brace(env: &mut Env) -> Symbol {
    if valid(env, START_BRACE) {
        push_context(env, BRACES, 0);
        return finish(START_BRACE);
    }
    FAIL
}

unsafe fn end_brace(env: &mut Env) -> Symbol {
    if valid(env, END_BRACE) && current_context(env) == BRACES {
        pop(env);
        return finish(END_BRACE);
    }
    FAIL
}

unsafe fn valid_layout_start_sym(env: &Env) -> Symbol {
    let mut i = START;
    while i < END {
        if valid(env, i) {
            return i;
        }
        i += 1;
    }
    FAIL
}

fn layout_sort(s: Symbol) -> ContextSort {
    match s {
        START_DO => DO_LAYOUT,
        START_CASE => CASE_LAYOUT,
        START_IF => MULTI_WAY_IF_LAYOUT,
        START_LET => LET_LAYOUT,
        START_QUOTE => QUOTE_LAYOUT,
        _ => DECL_LAYOUT,
    }
}

#[derive(Clone, Copy)]
struct StartLayout {
    sym: Symbol,
    sort: ContextSort,
}

unsafe fn valid_layout_start(env: &mut Env, next: Lexed) -> StartLayout {
    let mut start = StartLayout {
        sym: valid_layout_start_sym(env),
        sort: NO_CONTEXT,
    };
    if uninitialized(env) || start.sym == FAIL {
        return start;
    }
    let mut sort = layout_sort(start.sym);
    match next {
        L_BAR => {}
        L_BRACE_OPEN => {
            if newline_active(env) {
                return start;
            }
            sort = BRACES;
            start.sym = START_EXPLICIT;
        }
        _ => {
            if sort == MULTI_WAY_IF_LAYOUT {
                return start;
            }
        }
    }
    start.sort = sort;
    start
}

fn indent_can_start_layout(env: &Env, sort: ContextSort, indent: u32) -> bool {
    if current_context(env) == BRACES {
        return true;
    }
    let cur = current_indent(env);
    indent > cur || (indent == cur && sort == DO_LAYOUT)
}

unsafe fn start_layout(env: &mut Env, start: StartLayout, indent: u32) -> Symbol {
    if in_module_header(env) {
        pop(env);
    } else if start.sort == BRACES {
        mark(env);
    } else if !indent_can_start_layout(env, start.sort, indent) {
        return FAIL;
    }
    push_context(env, start.sort, indent);
    finish(start.sym)
}

unsafe fn start_layout_interior(env: &mut Env, next: Lexed) -> Symbol {
    let start = valid_layout_start(env, next);
    if start.sort == NO_CONTEXT {
        return FAIL;
    }
    let col = start_column(env);
    start_layout(env, start, col)
}

unsafe fn start_layout_newline(env: &mut Env) -> Symbol {
    let end = env.state.newline.end;
    let start = valid_layout_start(env, end);
    if start.sort == NO_CONTEXT {
        return FAIL;
    }
    let indent = env.state.newline.indent;
    let result = start_layout(env, start, indent);
    if result != FAIL {
        env.state.newline.no_semi = true;
    }
    result
}

unsafe fn texp_context(env: &mut Env) -> Symbol {
    if valid(env, START_TEXP) {
        push_context(env, T_EXP, 0);
        finish(START_TEXP)
    } else if valid(env, END_TEXP) && current_context(env) == T_EXP {
        pop(env);
        finish(END_TEXP)
    } else {
        FAIL
    }
}

// ---------------------------------------------------------------------------------------------
// Ending layouts
// ---------------------------------------------------------------------------------------------

fn end_layout_unchecked(env: &mut Env) -> Symbol {
    pop(env);
    finish(END)
}

unsafe fn end_layout(env: &mut Env) -> Symbol {
    if valid(env, END) {
        end_layout_unchecked(env)
    } else {
        FAIL
    }
}

unsafe fn end_layout_brace(env: &mut Env) -> Symbol {
    if valid(env, END_EXPLICIT) && current_context(env) == BRACES {
        advance_over(env, 0);
        mark(env);
        pop(env);
        finish(END_EXPLICIT)
    } else {
        FAIL
    }
}

unsafe fn end_layout_indent(env: &mut Env) -> Symbol {
    if valid(env, END) && indent_less(env, env.state.newline.indent) {
        if top_layout(env) {
            let indent = env.state.newline.indent;
            env.state.contexts.last_mut().unwrap().indent = indent;
            return update_state();
        } else {
            env.state.newline.skip_semi = false;
            return end_layout_unchecked(env);
        }
    }
    FAIL
}

unsafe fn end_layout_infix(env: &mut Env) -> Symbol {
    if !valid(env, VARSYM) && !valid(env, CONSYM) {
        return end_layout(env);
    }
    FAIL
}

unsafe fn end_layout_where(env: &mut Env) -> Symbol {
    if valid(env, END) && !valid(env, WHERE) && is_layout_context(env) {
        return end_layout(env);
    }
    FAIL
}

unsafe fn end_layout_in(env: &mut Env) -> Symbol {
    if valid(env, END) && (!valid(env, IN) || current_context(env) == LET_LAYOUT) {
        return end_layout(env);
    }
    FAIL
}

unsafe fn end_layout_deriving(env: &mut Env) -> Symbol {
    if valid(env, END)
        && !valid(env, DERIVING)
        && !top_layout(env)
        && current_context(env) == DECL_LAYOUT
    {
        return end_layout(env);
    }
    FAIL
}

fn layouts_in_texp(env: &Env) -> bool {
    if is_layout_context(env) && env.state.contexts.len() > 1 {
        let mut i = env.state.contexts.len() as i32 - 2;
        while i >= 0 {
            let cur = &env.state.contexts[i as usize];
            if cur.sort == T_EXP || cur.sort == BRACES {
                return true;
            } else if cur.sort > BRACES {
                break;
            }
            i -= 1;
        }
    }
    false
}

unsafe fn token_end_layout_texp(env: &mut Env) -> Symbol {
    if valid(env, END) && layouts_in_texp(env) {
        end_layout(env)
    } else {
        FAIL
    }
}

unsafe fn force_end_context(env: &mut Env) -> Symbol {
    let mut i = env.state.contexts.len() as i32 - 1;
    while i >= 0 {
        let ctx = env.state.contexts[i as usize].sort;
        let s = context_end_sym(ctx);
        pop(env);
        if s != FAIL && valid(env, s) {
            return finish(s);
        }
        i -= 1;
    }
    FAIL
}

// ---------------------------------------------------------------------------------------------
// Operators
// ---------------------------------------------------------------------------------------------

unsafe fn opening_token(env: &mut Env, i: u32) -> bool {
    let c = peek(env, i);
    match c {
        0x27e6 | 0x2987 => true,                            // ⟦ ⦇
        0x28 | 0x5b | 0x22 => true,                         // ( [ "
        0x7b => peek(env, i.wrapping_add(1)) != '-' as i32, // {
        _ => is_id_char(c),
    }
}

fn valid_symop_two_chars(first_char: i32, second_char: i32) -> bool {
    match first_char {
        0x3d => second_char != '>' as i32, // '='
        0x3c => second_char != '-' as i32, // '<'
        0x3a => second_char != ':' as i32, // ':'
        _ => true,
    }
}

unsafe fn lex_prefix(env: &mut Env, t: Lexed) -> Lexed {
    if opening_token(env, 1) { t } else { L_SYMOP }
}

fn lex_splice(c: i32) -> Lexed {
    if varid_start_char(c) || c == '(' as i32 {
        L_DOLLAR
    } else {
        L_SYMOP
    }
}

unsafe fn lex_symop(env: &mut Env) -> Lexed {
    let len = symop_lookahead(env);
    if len == 0 {
        return L_NOTHING;
    }
    let c1 = unsafe_peek(env, 0);
    if len == 1 {
        match c1 {
            0x3f => {
                // '?'
                let c = peek1(env);
                return if varid_start_char(c) {
                    L_NOTHING
                } else {
                    L_SYMOP
                };
            }
            0x23 => {
                // '#'
                return if char1(env, ')' as i32) {
                    L_UNBOXED_CLOSE
                } else {
                    L_HASH
                };
            }
            0x7c => {
                // '|'
                return if char1(env, ']' as i32) {
                    L_QUOTE_CLOSE
                } else {
                    L_BAR
                };
            }
            0x21 => return lex_prefix(env, L_BANG),
            0x7e => return lex_prefix(env, L_TILDE),
            0x40 => return lex_prefix(env, L_AT),
            0x25 => return lex_prefix(env, L_PERCENT),
            0x24 => {
                // '$'
                let c = peek1(env);
                return lex_splice(c);
            }
            0x2e => {
                // '.'
                let c = peek1(env);
                if is_id_char(c) {
                    return L_DOT_ID;
                } else if opening_token(env, 1) {
                    return L_DOT_OPEN;
                } else {
                    return L_SYMOP;
                }
            }
            0x2192 | 0x22b8 => return L_ARROW,
            0x21d2 => return L_C_ARROW,
            0x3d | 0x27e7 | 0x2988 => return L_TEXP_CLOSER,
            0x2a | 0x2d => return L_SYMOP_SPECIAL,
            0x5c | 0x2190 | 0x2200 | 0x2237 | 0x2605 | 0x27e6 | 0x2919 | 0x291a | 0x291b
            | 0x291c | 0x2987 => return L_NOTHING,
            _ => {}
        }
    } else if len == 2 {
        if seq(env, "->") {
            return L_ARROW;
        }
        if seq(env, "=>") {
            return L_C_ARROW;
        }
        let c2 = unsafe_peek(env, 1);
        match c1 {
            0x24 => {
                if c2 == '$' as i32 {
                    let c = peek2(env);
                    return lex_splice(c);
                }
            }
            0x7c => {
                if c2 == '|' as i32 && char2(env, ']' as i32) {
                    return L_QUOTE_CLOSE;
                }
            }
            0x2e => {
                if c2 == '.' as i32 {
                    return L_DOT_DOT;
                } else {
                    return L_DOT_SYMOP;
                }
            }
            0x23 => {
                if c2 == '#' as i32 || c2 == '|' as i32 {
                    return L_SYMOP_SPECIAL;
                }
            }
            _ => {
                if !valid_symop_two_chars(c1, c2) {
                    return L_NOTHING;
                }
            }
        }
    } else {
        match c1 {
            0x2d => {
                if seq(env, "->.") {
                    return L_ARROW;
                }
            }
            0x2e => return L_DOT_SYMOP,
            _ => {}
        }
    }
    L_SYMOP
}

unsafe fn left_section_op(env: &mut Env, start: u32) -> Symbol {
    if valid(env, LEFT_SECTION_OP) {
        advance_before(env, start);
        let space = skip_whitespace(env);
        if char_at(env, start, ')' as i32) {
            return finish(LEFT_SECTION_OP);
        }
        if space != NO_SPACE {
            return finish_if_valid(env, NO_SECTION_OP);
        }
    }
    FAIL
}

unsafe fn left_section_ticked(env: &mut Env) -> Symbol {
    if valid(env, LEFT_SECTION_OP) {
        let end_tick = advance_until_char(env, 1, '`' as i32);
        // Could be EOF
        if char_at(env, end_tick, '`' as i32) {
            return left_section_op(env, end_tick.wrapping_add(1));
        }
    }
    FAIL
}

unsafe fn finish_symop(env: &mut Env, s: Symbol) -> Symbol {
    if valid(env, s) || valid(env, LEFT_SECTION_OP) {
        let after_symop = symop_lookahead(env);
        SEQ!(left_section_op(env, after_symop));
        mark(env);
        return s;
    }
    FAIL
}

unsafe fn tight_op(env: &mut Env, whitespace: bool, s: Symbol) -> Symbol {
    if !whitespace {
        finish_if_valid(env, s)
    } else {
        FAIL
    }
}

unsafe fn prefix_or_varsym(env: &mut Env, whitespace: bool, s: Symbol) -> Symbol {
    if whitespace {
        SEQ!(finish_if_valid(env, s));
    }
    finish_symop(env, VARSYM)
}

unsafe fn tight_or_varsym(env: &mut Env, whitespace: bool, s: Symbol) -> Symbol {
    SEQ!(tight_op(env, whitespace, s));
    finish_symop(env, VARSYM)
}

unsafe fn infix_or_varsym(
    env: &mut Env,
    whitespace: bool,
    prefix: Symbol,
    tight: Symbol,
) -> Symbol {
    SEQ!(finish_if_valid(
        env,
        if whitespace { prefix } else { tight }
    ));
    finish_symop(env, VARSYM)
}

unsafe fn qualified_op(env: &mut Env) -> Symbol {
    if qualified_name(env, is_symop) == QUALIFIED_TARGET {
        let l = symop_lookahead(env);
        SEQ!(left_section_op(env, l));
        return QUALIFIED_OP;
    }
    FAIL
}

// ---------------------------------------------------------------------------------------------
// Token lookahead
// ---------------------------------------------------------------------------------------------

unsafe fn is_qq_start(env: &mut Env) -> bool {
    let end = advance_while(env, 1, quoter_char);
    char_at(env, end, '|' as i32)
}

unsafe fn try_end_token(env: &mut Env, target: &str, matched: Lexed) -> Lexed {
    if token(env, target) {
        matched
    } else {
        L_NOTHING
    }
}

unsafe fn only_minus(env: &mut Env) -> bool {
    let mut i: u32 = 2;
    while peek(env, i) == '-' as i32 {
        i = i.wrapping_add(1);
    }
    let c = peek(env, i);
    !symop_char(c)
}

unsafe fn line_comment_herald(env: &mut Env) -> bool {
    seq(env, "--") && only_minus(env)
}

unsafe fn lex_cpp(env: &mut Env) -> Lexed {
    match cpp_directive(env) {
        CPP_ELSE => L_CPP_ELSE,
        CPP_NOTHING => L_NOTHING,
        _ => L_CPP,
    }
}

unsafe fn lex_extras(env: &mut Env, bol: bool) -> Lexed {
    match peek0(env) {
        0x7b => {
            // '{'
            if char1(env, '-' as i32) {
                return if char2(env, '#' as i32) {
                    L_PRAGMA
                } else {
                    L_BLOCK_COMMENT
                };
            }
        }
        0x23 => {
            // '#'
            if bol {
                return lex_cpp(env);
            }
        }
        0x2d => {
            // '-'
            if line_comment_herald(env) {
                return L_LINE_COMMENT;
            }
        }
        _ => {}
    }
    L_NOTHING
}

unsafe fn lex(env: &mut Env, bol: bool) -> Lexed {
    SEQ!(lex_extras(env, bol));
    let c0 = peek0(env);
    if symop_char(c0) {
        SEQ!(lex_symop(env));
    } else {
        match peek0(env) {
            0x77 => return try_end_token(env, "where", L_WHERE),
            0x69 => return try_end_token(env, "in", L_IN),
            0x74 => return try_end_token(env, "then", L_THEN),
            0x65 => return try_end_token(env, "else", L_ELSE),
            0x64 => return try_end_token(env, "deriving", L_DERIVING),
            0x6d => {
                if (uninitialized(env) || in_module_header(env)) && token(env, "module") {
                    return L_MODULE;
                }
            }
            0x7b => return L_BRACE_OPEN,
            0x7d => return L_BRACE_CLOSE,
            0x3b => return L_SEMI,
            0x60 => return L_TICK,
            0x5b => {
                if valid(env, QQ_START) && is_qq_start(env) {
                    return L_BRACKET_OPEN;
                }
            }
            0x5d | 0x29 | 0x2c => return L_TEXP_CLOSER,
            _ => {
                let c = peek0(env);
                if is_conid_start_char(c) {
                    return L_UPPER;
                }
            }
        }
    }
    L_NOTHING
}

// ---------------------------------------------------------------------------------------------
// CPP
// ---------------------------------------------------------------------------------------------

unsafe fn cpp_else(env: &mut Env, emit: bool) -> Symbol {
    let mut nesting: u32 = 1;
    loop {
        take_line_escaped_newline(env);
        if emit {
            mark(env);
        }
        s_advance(env);
        reset_lookahead(env);
        match cpp_directive(env) {
            CPP_START => nesting = nesting.wrapping_add(1),
            CPP_END => nesting = nesting.wrapping_sub(1),
            _ => {}
        }
        if !(not_eof(env) && nesting > 0) {
            break;
        }
    }
    if emit { finish(CPP) } else { FAIL }
}

unsafe fn cpp_line(env: &mut Env) -> Symbol {
    take_line_escaped_newline(env);
    finish_marked(env, CPP)
}

// ---------------------------------------------------------------------------------------------
// Comments
// ---------------------------------------------------------------------------------------------

unsafe fn comment_type(env: &mut Env) -> Symbol {
    let mut i: u32 = 2;
    while peek(env, i) == '-' as i32 {
        i = i.wrapping_add(1);
    }
    while not_eof(env) {
        let c = peek(env, i);
        i = i.wrapping_add(1);
        if c == '|' as i32 || c == '^' as i32 {
            return HADDOCK;
        } else if !is_space_char(c) {
            break;
        }
    }
    COMMENT
}

unsafe fn inline_comment(env: &mut Env) -> Symbol {
    let sym = comment_type(env);
    loop {
        take_line(env);
        mark(env);
        s_advance(env);
        reset_lookahead(env);
        if !line_comment_herald(env) {
            break;
        }
    }
    sym
}

unsafe fn consume_block_comment(env: &mut Env, mut col: u32) -> u32 {
    let mut level: u32 = 0;
    loop {
        if is_eof(env) {
            return col;
        }
        col = col.wrapping_add(1);
        match PEEK(env) {
            0x7b => {
                // '{'
                s_advance(env);
                if PEEK(env) == '-' as i32 {
                    s_advance(env);
                    col = col.wrapping_add(1);
                    level = level.wrapping_add(1);
                }
            }
            0x2d => {
                // '-'
                s_advance(env);
                if PEEK(env) == '}' as i32 {
                    s_advance(env);
                    col = col.wrapping_add(1);
                    if level == 0 {
                        return col;
                    }
                    level = level.wrapping_sub(1);
                }
            }
            0x0a | 0x0d | 0x0c => {
                s_advance(env);
                col = 0;
            }
            0x09 => {
                s_advance(env);
                col = col.wrapping_add(7);
            }
            _ => {
                s_advance(env);
            }
        }
    }
}

unsafe fn block_comment(env: &mut Env) -> Symbol {
    let sym = comment_type(env);
    let size = la_size(env);
    consume_block_comment(env, size);
    finish_marked(env, sym)
}

// ---------------------------------------------------------------------------------------------
// Pragma
// ---------------------------------------------------------------------------------------------

unsafe fn consume_pragma(env: &mut Env) -> bool {
    if seq(env, "{-#") {
        while !seq(env, "#-}") && not_eof(env) {
            reset_lookahead(env);
            advance_over(env, 0);
        }
        return true;
    }
    false
}

unsafe fn pragma(env: &mut Env) -> Symbol {
    if consume_pragma(env) {
        mark(env);
        if env.state.newline.state != N_INACTIVE {
            env.state.newline.state = N_RESUME;
        }
        return finish(PRAGMA);
    }
    FAIL
}

// ---------------------------------------------------------------------------------------------
// Quasiquote
// ---------------------------------------------------------------------------------------------

unsafe fn qq_body(env: &mut Env) -> Symbol {
    loop {
        if is_eof(env) {
            return finish(QQ_BODY);
        } else if PEEK(env) == 0x27e7 {
            return finish_marked(env, QQ_BODY);
        } else if PEEK(env) == '|' as i32 {
            mark(env);
            s_advance(env);
            if PEEK(env) == ']' as i32 {
                return finish(QQ_BODY);
            }
        } else {
            s_advance(env);
        }
    }
}

// ---------------------------------------------------------------------------------------------
// Semicolon
// ---------------------------------------------------------------------------------------------

unsafe fn explicit_semicolon(env: &mut Env) -> Symbol {
    if valid(env, SEMICOLON) && !env.state.newline.skip_semi {
        env.state.newline.skip_semi = true;
        return update_state();
    }
    FAIL
}

unsafe fn resolve_semicolon(env: &mut Env, next: Lexed) -> Symbol {
    if env.state.newline.skip_semi {
        match next {
            L_LINE_COMMENT | L_BLOCK_COMMENT | L_PRAGMA | L_SEMI => {}
            _ => {
                env.state.newline.skip_semi = false;
                return update_state();
            }
        }
    }
    FAIL
}

unsafe fn semicolon(env: &mut Env) -> Symbol {
    if is_semicolon_context(env)
        && !(env.state.newline.no_semi || env.state.newline.skip_semi)
        && indent_lesseq(env, env.state.newline.indent)
    {
        env.state.newline.no_semi = true;
        finish(SEMICOLON)
    } else {
        FAIL
    }
}

// ---------------------------------------------------------------------------------------------
// High-level `Lexed` dispatch
// ---------------------------------------------------------------------------------------------

unsafe fn process_token_safe(env: &mut Env, next: Lexed) -> Symbol {
    match next {
        L_WHERE => return end_layout_where(env),
        L_IN => return end_layout_in(env),
        L_THEN | L_ELSE => return end_layout(env),
        L_DERIVING => return end_layout_deriving(env),
        L_BAR => {
            if !valid(env, BAR) {
                return end_layout(env);
            }
        }
        L_PRAGMA => return pragma(env),
        L_BLOCK_COMMENT => return block_comment(env),
        L_LINE_COMMENT => return inline_comment(env),
        L_CPP_ELSE => return cpp_else(env, true),
        L_CPP => return cpp_line(env),
        L_SYMOP | L_TICK | L_HASH => return end_layout_infix(env),
        L_UNBOXED_CLOSE => {
            SEQ!(token_end_layout_texp(env));
            return end_layout_infix(env);
        }
        L_ARROW => {
            if !valid(env, ARROW) {
                return token_end_layout_texp(env);
            }
        }
        L_TEXP_CLOSER => return token_end_layout_texp(env),
        L_QUOTE_CLOSE => return end_layout(env),
        _ => {}
    }
    FAIL
}

unsafe fn process_token_symop(env: &mut Env, whitespace: bool, next: Lexed) -> Symbol {
    match next {
        L_DOT_DOT => {
            SEQ!(finish_if_valid(env, DOTDOT));
            return tight_op(env, whitespace, QUAL_DOT);
        }
        L_DOT_ID => {
            SEQ!(finish_if_valid(
                env,
                if whitespace { PREFIX_DOT } else { TIGHT_DOT }
            ));
            return tight_op(env, whitespace, QUAL_DOT);
        }
        L_DOT_SYMOP => return tight_or_varsym(env, whitespace, QUAL_DOT),
        L_DOT_OPEN => return prefix_or_varsym(env, whitespace, PREFIX_DOT),
        L_BANG => return infix_or_varsym(env, whitespace, PREFIX_BANG, TIGHT_BANG),
        L_TILDE => return infix_or_varsym(env, whitespace, PREFIX_TILDE, TIGHT_TILDE),
        L_AT => return infix_or_varsym(env, whitespace, PREFIX_AT, TIGHT_AT),
        L_PERCENT => return prefix_or_varsym(env, whitespace, PREFIX_PERCENT),
        L_SYMOP => {
            if char0(env, ':' as i32) {
                return finish_symop(env, CONSYM);
            } else {
                return finish_symop(env, VARSYM);
            }
        }
        L_SYMOP_SPECIAL => {
            let l = symop_lookahead(env);
            SEQ!(left_section_op(env, l));
            if valid(env, MINUS) && match_symop(env, "-") {
                return finish(MINUS);
            }
        }
        L_UNBOXED_CLOSE | L_HASH => {
            let l = symop_lookahead(env);
            return left_section_op(env, l);
        }
        L_TICK => return left_section_ticked(env),
        L_UPPER => {
            if valid(env, QUALIFIED_OP) || valid(env, LEFT_SECTION_OP) {
                SEQ!(qualified_op(env));
            }
        }
        _ => {}
    }
    FAIL
}

unsafe fn process_token_splice(env: &mut Env, next: Lexed) -> Symbol {
    match next {
        L_DOLLAR => finish_if_valid(env, SPLICE),
        _ => FAIL,
    }
}

unsafe fn process_token_interior(env: &mut Env, next: Lexed) -> Symbol {
    match next {
        L_BRACE_CLOSE => {
            SEQ!(end_layout_brace(env));
            return token_end_layout_texp(env);
        }
        // Skip layout start
        L_MODULE => return FAIL,
        L_SEMI => return explicit_semicolon(env),
        L_BRACKET_OPEN => return finish(QQ_START),
        _ => {}
    }
    SEQ!(process_token_safe(env, next));
    start_layout_interior(env, next)
}

unsafe fn process_token_init(env: &mut Env, indent: u32, next: Lexed) -> Symbol {
    match next {
        L_MODULE => {
            push_context(env, MODULE_HEADER, 0);
            update_state()
        }
        L_BRACE_OPEN => {
            advance_over(env, 0);
            mark(env);
            push_context(env, BRACES, indent);
            finish(START_EXPLICIT)
        }
        _ => {
            push_context(env, DECL_LAYOUT, indent);
            finish(START)
        }
    }
}

// ---------------------------------------------------------------------------------------------
// Newline actions
// ---------------------------------------------------------------------------------------------

unsafe fn newline_extras(env: &mut Env, space: Space) -> Symbol {
    let bol = space == BOL || (space == NO_SPACE && newline_init(env));
    let next = lex_extras(env, bol);
    process_token_safe(env, next)
}

unsafe fn newline_process(env: &mut Env) -> Symbol {
    let indent = env.state.newline.indent;
    let end = env.state.newline.end;
    SEQ!(end_layout_indent(env));
    SEQ!(process_token_safe(env, end));
    let space = skip_whitespace(env);
    mark(env);
    if env.state.newline.unsafe_ {
        SEQ!(newline_extras(env, space));
    }
    if !env.state.newline.eof {
        SEQ!(start_layout_newline(env));
    }
    SEQ!(semicolon(env));
    reset_newline(env);
    if uninitialized(env) {
        SEQ!(process_token_init(env, indent, end));
    } else {
        SEQ!(process_token_symop(env, true, end));
        SEQ!(process_token_splice(env, end));
    }
    update_state()
}

unsafe fn newline_post(env: &mut Env) -> Symbol {
    let res = newline_process(env);
    if newline_init(env) {
        env.state.newline.state = N_PROCESS;
    }
    res
}

/// `newline` points either at `env.state.newline` or at a local of `constraint_lookahead`; the
/// functions called in between never touch `env.state.newline`.
unsafe fn newline_lookahead(env: &mut Env, newline: *mut Newline) {
    loop {
        match peek0(env) {
            0x0a | 0x0d | 0x0c => {
                skip_over(env, 0);
                (*newline).indent = 0;
            }
            0x09 => {
                skip_over(env, 0);
                (*newline).indent = (*newline).indent.wrapping_add(8);
            }
            _ => {
                let c = peek0(env);
                if is_space_char(c) {
                    skip_over(env, 0);
                    (*newline).indent = (*newline).indent.wrapping_add(1);
                } else {
                    (*newline).end = lex(env, (*newline).indent == 0);
                    // Newlines without extras are only safe if `lex` didn't advance the lexer over
                    // non-whitespace.
                    (*newline).unsafe_ |= !no_lookahead(env);
                    match (*newline).end {
                        L_EOF => {
                            (*newline).indent = 0;
                            (*newline).eof = true;
                            return;
                        }
                        L_THEN | L_ELSE | L_SEMI => {
                            (*newline).no_semi = true;
                            return;
                        }
                        L_BLOCK_COMMENT => {
                            let col = (*newline).indent.wrapping_add(2);
                            (*newline).indent = consume_block_comment(env, col);
                        }
                        L_LINE_COMMENT => {
                            (*newline).indent = 0;
                            take_line(env);
                        }
                        L_CPP_ELSE => {
                            cpp_else(env, false);
                            take_line_escaped_newline(env);
                        }
                        L_CPP => {
                            take_line_escaped_newline(env);
                        }
                        _ => return,
                    }
                }
            }
        }
        reset_lookahead(env);
    }
}

unsafe fn newline_start(env: &mut Env) -> Symbol {
    env.state.newline.state = N_INIT;
    let p: *mut Newline = &mut env.state.newline;
    newline_lookahead(env, p);
    if env.state.newline.unsafe_ {
        update_state()
    } else {
        newline_post(env)
    }
}

unsafe fn newline_resume(env: &mut Env) -> Symbol {
    let indent = env.state.newline.indent;
    skip_space(env);
    reset_newline(env);
    env.state.newline.indent = indent;
    newline_start(env)
}

// ---------------------------------------------------------------------------------------------
// Constraints
// ---------------------------------------------------------------------------------------------

type CtrResult = u32;
const CTR_UNDECIDED: CtrResult = 0;
const CTR_IMPOSSIBLE: CtrResult = 1;
const CTR_ARROW_FOUND: CtrResult = 2;
const CTR_INFIX_FOUND: CtrResult = 3;
const CTR_EQUALS_FOUND: CtrResult = 4;
const CTR_BAR_FOUND: CtrResult = 5;

#[derive(Default)]
struct CtrState {
    reset: u32,
    brackets: u32,
    context: bool,
    infix: bool,
    data_infix: bool,
    type_instance: bool,
}

fn ctr_bracket_open(state: &mut CtrState) -> CtrResult {
    state.brackets = state.brackets.wrapping_add(1);
    state.reset = 1;
    CTR_UNDECIDED
}

fn ctr_bracket_close(state: &mut CtrState) -> CtrResult {
    if state.brackets == 0 {
        return CTR_IMPOSSIBLE;
    }
    state.brackets -= 1;
    state.reset = 1;
    CTR_UNDECIDED
}

unsafe fn ctr_stop_on_token(env: &mut Env, target: &str) -> CtrResult {
    if token(env, target) {
        CTR_IMPOSSIBLE
    } else {
        CTR_UNDECIDED
    }
}

unsafe fn ctr_top(env: &mut Env, next: Lexed) -> CtrResult {
    match next {
        L_C_ARROW => return CTR_ARROW_FOUND,
        L_SYMOP | L_SYMOP_SPECIAL | L_TILDE | L_TICK => return CTR_INFIX_FOUND,
        L_BAR => return CTR_BAR_FOUND,
        L_ARROW | L_WHERE | L_DOT_DOT | L_SEMI => {}
        L_TEXP_CLOSER => {
            if peek0(env) == '=' as i32 {
                return CTR_EQUALS_FOUND;
            }
        }
        _ => match peek0(env) {
            0x3d => return CTR_EQUALS_FOUND, // '='
            0x2200 => {}
            0x3a => {
                // ':'
                if !char1(env, ':' as i32) {
                    return CTR_UNDECIDED;
                }
            }
            0x66 => {
                // 'f'
                SEQ!(ctr_stop_on_token(env, "forall"));
                return ctr_stop_on_token(env, "family");
            }
            0x69 => return ctr_stop_on_token(env, "instance"), // 'i'
            _ => return CTR_UNDECIDED,
        },
    }
    CTR_IMPOSSIBLE
}

unsafe fn ctr_lookahead_step(env: &mut Env, state: &mut CtrState, next: Lexed) -> CtrResult {
    state.reset = 1;
    match next {
        L_BRACE_CLOSE => return ctr_bracket_close(state),
        L_UNBOXED_CLOSE => {
            SEQ!(ctr_bracket_close(state));
            state.reset = 2;
            return CTR_UNDECIDED;
        }
        L_BRACE_OPEN => return ctr_bracket_open(state),
        L_SYMOP_SPECIAL | L_SYMOP => {
            state.reset = symop_lookahead(env);
        }
        L_UPPER => {
            state.reset = conid(env);
            return CTR_UNDECIDED;
        }
        L_DOT_ID => return CTR_UNDECIDED,
        L_PRAGMA => {
            if consume_pragma(env) {
                state.reset = 3;
            }
            return CTR_UNDECIDED;
        }
        L_TEXP_CLOSER | L_NOTHING => {
            match peek0(env) {
                0x29 | 0x5d => return ctr_bracket_close(state), // ) ]
                0x28 | 0x5b => return ctr_bracket_open(state),  // ( [
                0x22 => {
                    state.reset = take_string_literal(env);
                    return CTR_UNDECIDED;
                }
                0x27 => {
                    state.reset = take_char_literal(env);
                    return CTR_UNDECIDED;
                }
                _ => {
                    let c = peek0(env);
                    if varid_start_char(c) {
                        state.reset = advance_while(env, 1, is_id_char);
                    }
                }
            }
        }
        _ => {}
    }
    if state.brackets != 0 {
        return CTR_UNDECIDED;
    }
    ctr_top(env, next)
}

unsafe fn constraint_lookahead(env: &mut Env) -> Symbol {
    let mut state = CtrState::default();
    let mut done = false;
    while !done && not_eof(env) {
        // Setting indent to 99999 only to not trigger the following termination condition when no
        // newline was advanced over
        let mut newline = Newline {
            state: 0,
            indent: 99999,
            ..Newline::default()
        };
        newline_lookahead(env, &mut newline);
        if newline.indent <= current_indent(env) && current_context(env) != BRACES {
            break;
        }
        let result = ctr_lookahead_step(env, &mut state, newline.end);
        match result {
            CTR_ARROW_FOUND => {
                state.context = true;
                done = true;
            }
            CTR_INFIX_FOUND => {
                if char0(env, ':' as i32) || char0(env, '`' as i32) {
                    state.data_infix = true;
                }
                state.infix = true;
                done = !valid(env, CONTEXT);
            }
            CTR_EQUALS_FOUND => {
                done = !valid(env, TYPE_INSTANCE);
                state.type_instance = true;
            }
            CTR_BAR_FOUND => {
                done = true;
                state.type_instance = false;
            }
            CTR_IMPOSSIBLE => {
                done = true;
            }
            _ => {}
        }
        reset_lookahead_to(env, state.reset);
        state.reset = 0;
    }
    if state.context {
        SEQ!(finish_if_valid(env, CONTEXT));
    }
    if state.infix {
        SEQ!(finish_if_valid(env, INFIX));
    }
    if state.data_infix {
        SEQ!(finish_if_valid(env, DATA_INFIX));
    }
    if state.type_instance {
        SEQ!(finish_if_valid(env, TYPE_INSTANCE));
    }
    FAIL
}

// ---------------------------------------------------------------------------------------------
// Actions that are executed for interior positions
// ---------------------------------------------------------------------------------------------

unsafe fn process_token_constraint(env: &mut Env) -> Symbol {
    if valid(env, CONTEXT)
        || valid(env, INFIX)
        || valid(env, DATA_INFIX)
        || valid(env, TYPE_INSTANCE)
    {
        return constraint_lookahead(env);
    }
    FAIL
}

unsafe fn interior(env: &mut Env, whitespace: bool) -> Symbol {
    let next = lex(env, false);
    SEQ!(resolve_semicolon(env, next));
    SEQ!(process_token_interior(env, next));
    SEQ!(process_token_symop(env, whitespace, next));
    SEQ!(process_token_constraint(env));
    SEQ!(process_token_splice(env, next));
    FAIL
}

// ---------------------------------------------------------------------------------------------
// Initial actions
// ---------------------------------------------------------------------------------------------

unsafe fn pre_ws_commands(env: &mut Env) -> Symbol {
    SEQ!(texp_context(env));
    SEQ!(start_brace(env));
    SEQ!(end_brace(env));
    // Leading whitespace must be included in the node.
    if valid(env, QQ_BODY) {
        return qq_body(env);
    }
    if newline_active(env) {
        SEQ!(newline_post(env));
    } else if env.state.newline.state == N_RESUME {
        SEQ!(newline_resume(env));
    }
    FAIL
}

unsafe fn scan_main(env: &mut Env) -> Symbol {
    mark(env);
    SEQ!(pre_ws_commands(env));
    let whitespace = skip_space(env);
    if is_newline(PEEK(env)) {
        return newline_start(env);
    } else if not_eof(env) {
        return interior(env, whitespace);
    }
    FAIL
}

unsafe fn process_result(env: &mut Env, mut result: Symbol) -> bool {
    if result == FAIL && is_eof(env) && no_lookahead(env) {
        mark(env);
        // Inlined `end_layout` because of perf glitch
        if valid(env, END) {
            result = end_layout_unchecked(env);
        } else if valid(env, SEMICOLON) {
            result = finish(SEMICOLON);
        } else {
            result = force_end_context(env);
        }
    }
    set_result_symbol(env, result)
}

unsafe fn scan(env: &mut Env) -> bool {
    if after_error(env) {
        return false;
    }
    let result = scan_main(env);
    process_result(env, result)
}

// ---------------------------------------------------------------------------------------------
// API
// ---------------------------------------------------------------------------------------------

/// Serialized header: `contexts` count, then the 16 byte `Newline`.
const PERSIST_SIZE: usize = 20;
const CONTEXT_SIZE: usize = 8;

#[unsafe(no_mangle)]
pub unsafe extern "C" fn tree_sitter_haskell_external_scanner_create() -> *mut c_void {
    let state = State {
        contexts: Vec::with_capacity(8),
        newline: Newline::default(),
        lookahead: Lookahead {
            contents: Vec::with_capacity(8),
            offset: 0,
        },
    };
    Box::into_raw(Box::new(state)) as *mut c_void
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn tree_sitter_haskell_external_scanner_scan(
    payload: *mut c_void,
    lexer: *mut TSLexer,
    valid_symbols: *const bool,
) -> bool {
    let mut env = env_new(lexer, valid_symbols, &mut *(payload as *mut State));
    scan(&mut env)
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn tree_sitter_haskell_external_scanner_serialize(
    payload: *mut c_void,
    buffer: *mut c_char,
) -> u32 {
    let state = &*(payload as *const State);
    let n = state.newline;
    let contexts = state.contexts.len() as u32;
    let contexts_size = contexts.wrapping_mul(CONTEXT_SIZE as u32);
    let buf = buffer as *mut u8;
    let mut header = [0u8; PERSIST_SIZE];
    header[0..4].copy_from_slice(&contexts.to_ne_bytes());
    header[4..8].copy_from_slice(&n.state.to_ne_bytes());
    header[8..12].copy_from_slice(&n.end.to_ne_bytes());
    header[12..16].copy_from_slice(&n.indent.to_ne_bytes());
    header[16] = n.eof as u8;
    header[17] = n.no_semi as u8;
    header[18] = n.skip_semi as u8;
    header[19] = n.unsafe_ as u8;
    core::ptr::copy_nonoverlapping(header.as_ptr(), buf, PERSIST_SIZE);
    let to_copy = (PERSIST_SIZE as u32).wrapping_add(contexts_size);
    if to_copy > SERIALIZATION_BUFFER_SIZE {
        return 0;
    }
    let mut p = buf.add(PERSIST_SIZE);
    for c in state.contexts.iter() {
        core::ptr::copy_nonoverlapping(c.sort.to_ne_bytes().as_ptr(), p, 4);
        core::ptr::copy_nonoverlapping(c.indent.to_ne_bytes().as_ptr(), p.add(4), 4);
        p = p.add(CONTEXT_SIZE);
    }
    to_copy
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn tree_sitter_haskell_external_scanner_deserialize(
    payload: *mut c_void,
    buffer: *const c_char,
    length: u32,
) {
    let state = &mut *(payload as *mut State);
    let mut contexts_n: u32 = 0;
    let mut newline = Newline::default();
    let mut contexts: Vec<Context> = Vec::new();
    if length > 0 {
        // The C reads the header and the contexts straight from the buffer; here only the `length`
        // bytes that exist are read and anything missing (a corrupt buffer) reads as zero.
        let src = core::slice::from_raw_parts(buffer as *const u8, length as usize);
        let mut header = [0u8; PERSIST_SIZE];
        let h = core::cmp::min(PERSIST_SIZE, src.len());
        header[..h].copy_from_slice(&src[..h]);
        let rd =
            |o: usize| u32::from_ne_bytes([header[o], header[o + 1], header[o + 2], header[o + 3]]);
        contexts_n = rd(0);
        newline = Newline {
            state: rd(4),
            end: rd(8),
            indent: rd(12),
            eof: header[16] != 0,
            no_semi: header[17] != 0,
            skip_semi: header[18] != 0,
            unsafe_: header[19] != 0,
        };
        // A context count larger than what the buffer holds is clamped to the contexts present.
        let body = if src.len() > PERSIST_SIZE {
            &src[PERSIST_SIZE..]
        } else {
            &[][..]
        };
        let n = core::cmp::min(contexts_n as usize, body.len() / CONTEXT_SIZE);
        contexts_n = n as u32;
        for i in 0..n {
            let o = i * CONTEXT_SIZE;
            contexts.push(Context {
                sort: u32::from_ne_bytes([body[o], body[o + 1], body[o + 2], body[o + 3]]),
                indent: u32::from_ne_bytes([body[o + 4], body[o + 5], body[o + 6], body[o + 7]]),
            });
        }
    } else {
        newline.state = N_RESUME;
    }
    let _ = contexts_n;
    state.newline = newline;
    state.contexts = contexts;
    state.lookahead.contents.clear();
    state.lookahead.offset = 0;
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn tree_sitter_haskell_external_scanner_destroy(payload: *mut c_void) {
    if !payload.is_null() {
        drop(Box::from_raw(payload as *mut State));
    }
}

