// unicode.h (generated tables, copied verbatim; the five predicates are the C's, chained by range)
// ---------------------------------------------------------------------------------------------

fn bm(bitmap: &[u8], min: i32, c: i32) -> bool {
    let offset = c - min;
    (bitmap[(offset >> 3) as usize] as u32 & (1u32 << (offset & 7))) > 0
}

