fn is_identifier_char(c: i32) -> bool {
    if c < BITMAP_IDENTIFIER_1_MIN_CODEPOINT {
        return false;
    }
    if c <= BITMAP_IDENTIFIER_1_MAX_CODEPOINT {
        return bm(&BITMAP_IDENTIFIER_1, BITMAP_IDENTIFIER_1_MIN_CODEPOINT, c);
    }
    if c < BITMAP_IDENTIFIER_2_MIN_CODEPOINT {
        return false;
    }
    if c <= BITMAP_IDENTIFIER_2_MAX_CODEPOINT {
        return bm(&BITMAP_IDENTIFIER_2, BITMAP_IDENTIFIER_2_MIN_CODEPOINT, c);
    }
    if c < BITMAP_IDENTIFIER_3_MIN_CODEPOINT {
        return false;
    }
    if c <= BITMAP_IDENTIFIER_3_MAX_CODEPOINT {
        return bm(&BITMAP_IDENTIFIER_3, BITMAP_IDENTIFIER_3_MIN_CODEPOINT, c);
    }
    if c < BITMAP_IDENTIFIER_4_MIN_CODEPOINT {
        return false;
    }
    if c <= BITMAP_IDENTIFIER_4_MAX_CODEPOINT {
        return bm(&BITMAP_IDENTIFIER_4, BITMAP_IDENTIFIER_4_MIN_CODEPOINT, c);
    }
    if c < BITMAP_IDENTIFIER_5_MIN_CODEPOINT {
        return false;
    }
    if c <= BITMAP_IDENTIFIER_5_MAX_CODEPOINT {
        return bm(&BITMAP_IDENTIFIER_5, BITMAP_IDENTIFIER_5_MIN_CODEPOINT, c);
    }
    false
}

